package week_08.oop.assigment_problems;
import java.util.*;
public class CampusCanteenSmartCard {
 interface Plan{double price(double fullPrice);}static class DayScholar implements Plan{public double price(double p){return p;}}static class Hosteller implements Plan{public double price(double p){return p*.90;}}static class Staff implements Plan{public double price(double p){return p*.80;}}
 static class Transaction{String description;double amount;Transaction(String d,double a){description=d;amount=a;}}
 static class Purchase{String item;double charged;boolean refunded;Purchase(String i,double c){item=i;charged=c;}}
 static class Card{String id;Plan plan;double balance;boolean blocked;List<Transaction> history=new ArrayList<>();List<Purchase> purchases=new ArrayList<>();Card(String id,Plan p){this.id=id;plan=p;}void topUp(double amount){if(blocked)throw new IllegalStateException("Card blocked");if(amount<100||balance+amount>5000)throw new IllegalArgumentException("Top-up must be >= ₹100 and balance cannot exceed ₹5000");balance+=amount;history.add(new Transaction("Top-up",amount));}Purchase buy(String item,double price){if(blocked)throw new IllegalStateException("Card blocked");double charge=plan.price(price);if(charge>balance)throw new IllegalStateException("Insufficient balance");balance-=charge;history.add(new Transaction(item,-charge));Purchase p=new Purchase(item,charge);purchases.add(p);return p;}void refund(Purchase p){if(p.refunded)throw new IllegalStateException("Already refunded");p.refunded=true;balance+=p.charged;history.add(new Transaction("Refund "+p.item,p.charged));}void block(){blocked=true;}void unblock(){blocked=false;}void statement(){for(Transaction t:history)System.out.printf("%s: %+.2f%n",t.description,t.amount);System.out.printf("Balance: %.2f%n",balance);}}
 public static void main(String[]args){Card c=new Card("C-2045",new Hosteller());c.topUp(500);Purchase thali=c.buy("Veg Thali",120);c.buy("Cold Coffee",60);c.refund(thali);c.statement();}
}